pub const Uuid = struct {
    bytes: [16]u8,

    pub fn parse(text: []const u8) !Uuid {
        if (text.len != 36) return error.InvalidUuid;
        var out: [16]u8 = undefined;
        var oi: usize = 0;
        var i: usize = 0;
        while (i < text.len) : (i += 1) {
            const c = text[i];
            if (c == '-') continue;
            if (oi >= 32) return error.InvalidUuid;
            const hi = try hexNibble(c);
            i += 1;
            if (i >= text.len) return error.InvalidUuid;
            const lo = try hexNibble(text[i]);
            if (oi % 2 == 0) {
                out[oi / 2] = (hi << 4) | lo;
            } else {
                return error.InvalidUuid;
            }
            oi += 2;
        }
        if (oi != 32) return error.InvalidUuid;
        return .{ .bytes = out };
    }

    fn hexNibble(c: u8) !u8 {
        return switch (c) {
            '0'...'9' => c - '0',
            'a'...'f' => c - 'a' + 10,
            'A'...'F' => c - 'A' + 10,
            else => error.InvalidUuid,
        };
    }

    pub fn v4(rng: std.rand.Random) Uuid {
        var b: [16]u8 = undefined;
        rng.bytes(&b);
        b[6] = (b[6] & 0x0f) | 0x40;
        b[8] = (b[8] & 0x3f) | 0x80;
        return .{ .bytes = b };
    }

    pub fn toString(self: Uuid, allocator: Allocator) ![]u8 {
        var buf = try allocator.alloc(u8, 36);
        const hex = "0123456789abcdef";
        var i: usize = 0;
        var o: usize = 0;
        while (i < 16) : (i += 1) {
            if (o == 8 or o == 13 or o == 18 or o == 23) {
                buf[o] = '-';
                o += 1;
            }
            const v = self.bytes[i];
            buf[o] = hex[(v >> 4) & 0x0f];
            buf[o + 1] = hex[v & 0x0f];
            o += 2;
        }
        return buf;
    }
};

