fn runCurlJson(allocator: std.mem.Allocator, args: []const []const u8, max_bytes: usize) ![]u8 {
    var child = std.process.Child.init(args, allocator);
    child.stdin_behavior = .Ignore;
    child.stdout_behavior = .Pipe;
    child.stderr_behavior = .Pipe;
    try child.spawn();

    const stdout_bytes = try child.stdout.?.readToEndAlloc(allocator, max_bytes);
    _ = child.stderr.?.readToEndAlloc(allocator, max_bytes) catch &[_]u8{};
    const term = try child.wait();
    switch (term) {
        .Exited => |code| {
            if (code != 0) return error.HttpRequestFailed;
        },
        else => return error.HttpRequestFailed,
    }
    return stdout_bytes;
}

fn chooseApi(config: *const Config, model: []const u8) struct { api_url: []const u8, api_key: []const u8 } {
    if (std.mem.startsWith(u8, model, "grok")) {
        return .{ .api_url = config.xai_api_url, .api_key = config.xai_api_key };
    }
    return .{ .api_url = config.cerebras_api_url, .api_key = config.cerebras_api_key };
}

pub fn chatCompletion(
    allocator: std.mem.Allocator,
    config: *const Config,
    model: []const u8,
    system_prompt: []const u8,
    messages: []const ChatMessage,
) ![]u8 {
    const api = chooseApi(config, model);

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const a = arena.allocator();

    var all_messages_list = std.ArrayList(std.json.Value).init(a);
    try all_messages_list.append(.{ .object = try std.json.ObjectMap.init(a) });

    {
        var obj = &all_messages_list.items[0].object;
        try obj.put("role", .{ .string = "system" });
        try obj.put("content", .{ .string = system_prompt });
    }

    var i: usize = 0;
    while (i < messages.len) : (i += 1) {
        var v = std.json.Value{ .object = try std.json.ObjectMap.init(a) };
        try v.object.put("role", .{ .string = messages[i].role });
        try v.object.put("content", .{ .string = messages[i].content });
        try all_messages_list.append(v);
    }

    var root = std.json.Value{ .object = try std.json.ObjectMap.init(a) };
    try root.object.put("model", .{ .string = model });
    try root.object.put("messages", .{ .array = all_messages_list });
    try root.object.put("temperature", .{ .integer = 1 });
    try root.object.put("max_tokens", .{ .integer = 40960 });

    var body_buf = std.ArrayList(u8).init(a);
    try std.json.stringify(root, .{}, body_buf.writer());
    const body = body_buf.items;

    const url = try std.fmt.allocPrint(a, "{s}/chat/completions", .{api.api_url});
    const auth = try std.fmt.allocPrint(a, "Authorization: Bearer {s}", .{api.api_key});

    const argv = [_][]const u8{
        "curl",
        "-sS",
        "-X",
        "POST",
        url,
        "-H",
        auth,
        "-H",
        "Content-Type: application/json",
        "--data-binary",
        body,
    };

    const resp_bytes = try runCurlJson(allocator, &argv, 64 * 1024 * 1024);

    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, resp_bytes, .{});
    defer parsed.deinit();

    const choices = parsed.value.object.get("choices") orelse return error.MissingContent;
    if (choices != .array or choices.array.items.len == 0) return error.MissingContent;
    const msg = choices.array.items[0].object.get("message") orelse return error.MissingContent;
    const content = msg.object.get("content") orelse return error.MissingContent;
    if (content != .string) return error.MissingContent;

    return allocator.dupe(u8, content.string);
}

pub fn chatCompletionWithTools(
    allocator: std.mem.Allocator,
    config: *const Config,
    model: []const u8,
    system_prompt: []const u8,
    messages: []const ChatMessage,
    tools: []const ToolDefinition,
) !struct { content: []u8, tool_calls: []ToolCallRequest } {
    const api = chooseApi(config, model);

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const a = arena.allocator();

    var all_messages_list = std.ArrayList(std.json.Value).init(a);
    try all_messages_list.append(.{ .object = try std.json.ObjectMap.init(a) });
    {
        var obj = &all_messages_list.items[0].object;
        try obj.put("role", .{ .string = "system" });
        try obj.put("content", .{ .string = system_prompt });
    }
    var mi: usize = 0;
    while (mi < messages.len) : (mi += 1) {
        var v = std.json.Value{ .object = try std.json.ObjectMap.init(a) };
        try v.object.put("role", .{ .string = messages[mi].role });
        try v.object.put("content", .{ .string = messages[mi].content });
        try all_messages_list.append(v);
    }

    var tools_list = std.ArrayList(std.json.Value).init(a);
    var ti: usize = 0;
    while (ti < tools.len) : (ti += 1) {
        var fn_obj = std.json.Value{ .object = try std.json.ObjectMap.init(a) };
        try fn_obj.object.put("name", .{ .string = tools[ti].name });
        try fn_obj.object.put("description", .{ .string = tools[ti].description });
        try fn_obj.object.put("parameters", tools[ti].parameters);

        var tool_obj = std.json.Value{ .object = try std.json.ObjectMap.init(a) };
        try tool_obj.object.put("type", .{ .string = "function" });
        try tool_obj.object.put("function", fn_obj);
        try tools_list.append(tool_obj);
    }

    var root = std.json.Value{ .object = try std.json.ObjectMap.init(a) };
    try root.object.put("model", .{ .string = model });
    try root.object.put("messages", .{ .array = all_messages_list });
    try root.object.put("tools", .{ .array = tools_list });
    try root.object.put("temperature", .{ .float = 0.7 });
    try root.object.put("max_tokens", .{ .integer = 4096 });

    var body_buf = std.ArrayList(u8).init(a);
    try std.json.stringify(root, .{}, body_buf.writer());
    const body = body_buf.items;

    const url = try std.fmt.allocPrint(a, "{s}/chat/completions", .{api.api_url});
    const auth = try std.fmt.allocPrint(a, "Authorization: Bearer {s}", .{api.api_key});

    const argv = [_][]const u8{
        "curl",
        "-sS",
        "-X",
        "POST",
        url,
        "-H",
        auth,
        "-H",
        "Content-Type: application/json",
        "--data-binary",
        body,
    };

    const resp_bytes = try runCurlJson(allocator, &argv, 64 * 1024 * 1024);

    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, resp_bytes, .{});
    defer parsed.deinit();

    const choices = parsed.value.object.get("choices") orelse return error.MissingContent;
    if (choices != .array or choices.array.items.len == 0) return error.MissingContent;
    const msg = choices.array.items[0].object.get("message") orelse return error.MissingContent;

    const content_val = msg.object.get("content") orelse std.json.Value{ .string = "" };
    const content = if (content_val == .string) content_val.string else "";

    var tool_calls_list = std.ArrayList(ToolCallRequest).init(allocator);
    const tool_calls_val_opt = msg.object.get("tool_calls");
    if (tool_calls_val_opt) |tool_calls_val| {
        if (tool_calls_val == .array) {
            var ci: usize = 0;
            while (ci < tool_calls_val.array.items.len) : (ci += 1) {
                const call = tool_calls_val.array.items[ci];
                const idv = call.object.get("id") orelse continue;
                const fnv = call.object.get("function") orelse continue;
                const namev = fnv.object.get("name") orelse continue;
                const argsv = fnv.object.get("arguments") orelse continue;
                if (idv != .string or namev != .string or argsv != .string) continue;

                var args_parsed = std.json.parseFromSlice(std.json.Value, allocator, argsv.string, .{}) catch continue;
                defer args_parsed.deinit();

                const id_s = try allocator.dupe(u8, idv.string);
                const name_s = try allocator.dupe(u8, namev.string);
                const args_copy = try cloneJsonValue(allocator, args_parsed.value);

                try tool_calls_list.append(.{
                    .id = id_s,
                    .name = name_s,
                    .arguments = args_copy,
                });
            }
        }
    }

    return .{
        .content = try allocator.dupe(u8, content),
        .tool_calls = try tool_calls_list.toOwnedSlice(),
    };
}

