pub fn estimatePlanCost(steps: []const PlanStep) PlanCostEstimate {
    var file_reads: usize = 0;
    var file_writes: usize = 0;
    var shell_commands: usize = 0;
    var web_requests: usize = 0;

    for (steps) |step| {
        if (std.mem.eql(u8, step.tool, "file_read")) {
            file_reads += 1;
        } else if (std.mem.eql(u8, step.tool, "file_write") or std.mem.eql(u8, step.tool, "apply_patch")) {
            file_writes += 1;
        } else if (std.mem.eql(u8, step.tool, "shell_run")) {
            shell_commands += 1;
        } else if (std.mem.eql(u8, step.tool, "web_search") or std.mem.eql(u8, step.tool, "web_fetch")) {
            web_requests += 1;
        }
    }

    const estimated_time_secs: u64 =
        @as(u64, file_reads) +
        @as(u64, file_writes) * 2 +
        @as(u64, shell_commands) * 5 +
        @as(u64, web_requests) * 3;

    return .{
        .total_steps = steps.len,
        .file_reads = file_reads,
        .file_writes = file_writes,
        .shell_commands = shell_commands,
        .web_requests = web_requests,
        .estimated_time_secs = estimated_time_secs,
    };
}

