fn parseHunkHeader(line: []const u8) ?struct { old_start: usize, old_count: usize, new_start: usize, new_count: usize } {
    if (line.len < 4) return null;
    if (!(line[0] == '@' and line[1] == '@')) return null;

    var i: usize = 2;
    while (i < line.len and line[i] == ' ') : (i += 1) {}

    if (i >= line.len or line[i] != '-') return null;
    i += 1;
    const old_start = parseNumber(line, &i) orelse return null;
    var old_count: usize = 1;
    if (i < line.len and line[i] == ',') {
        i += 1;
        old_count = parseNumber(line, &i) orelse return null;
    }

    while (i < line.len and line[i] == ' ') : (i += 1) {}
    if (i >= line.len or line[i] != '+') return null;
    i += 1;
    const new_start = parseNumber(line, &i) orelse return null;
    var new_count: usize = 1;
    if (i < line.len and line[i] == ',') {
        i += 1;
        new_count = parseNumber(line, &i) orelse return null;
    }

    return .{ .old_start = old_start, .old_count = old_count, .new_start = new_start, .new_count = new_count };
}

fn parseNumber(s: []const u8, idx: *usize) ?usize {
    var i = idx.*;
    if (i >= s.len) return null;
    var n: usize = 0;
    var any = false;
    while (i < s.len) : (i += 1) {
        const c = s[i];
        if (c < '0' or c > '9') break;
        any = true;
        n = n * 10 + @as(usize, c - '0');
    }
    if (!any) return null;
    idx.* = i;
    return n;
}

fn applyUnifiedDiff(allocator: std.mem.Allocator, original: []const u8, patch: []const u8) ![]u8 {
    var lines = std.ArrayList([]u8).init(allocator);
    defer lines.deinit();

    var orig_it = std.mem.splitScalar(u8, original, '\n');
    while (orig_it.next()) |ln| {
        try lines.append(try allocator.dupe(u8, ln));
    }

    var patch_lines = std.ArrayList([]const u8).init(allocator);
    defer patch_lines.deinit();
    var pit = std.mem.splitScalar(u8, patch, '\n');
    while (pit.next()) |ln| {
        try patch_lines.append(ln);
    }

    var i: usize = 0;
    while (i < patch_lines.items.len) {
        const line = patch_lines.items[i];
        if (std.mem.startsWith(u8, line, "@@")) {
            if (parseHunkHeader(line)) |hunk| {
                var current_line: usize = if (hunk.old_start == 0) 0 else hunk.old_start - 1;
                i += 1;
                while (i < patch_lines.items.len and !std.mem.startsWith(u8, patch_lines.items[i], "@@")) {
                    const pl = patch_lines.items[i];
                    if (pl.len > 0 and pl[0] == '-') {
                        if (current_line < lines.items.len) {
                            _ = lines.orderedRemove(current_line);
                        }
                    } else if (pl.len > 0 and pl[0] == '+') {
                        const content = pl[1..];
                        if (current_line <= lines.items.len) {
                            try lines.insert(current_line, try allocator.dupe(u8, content));
                            current_line += 1;
                        }
                    } else if ((pl.len > 0 and pl[0] == ' ') or pl.len == 0) {
                        current_line += 1;
