const std = @import("std");
const Config = @import("config.zig").Config;
const llm = @import("llm.zig");

pub const PlanStep = struct {
    description: []const u8,
    tool: []const u8,
    args: std.json.Value,
};

pub const PlanCostEstimate = struct {
    total_steps: usize,
    file_reads: usize,
    file_writes: usize,
    shell_commands: usize,
    web_requests: usize,
    estimated_time_secs: u64,
};

pub fn createPlan(
    allocator: std.mem.Allocator,
    config: *const Config,
    prompt: []const u8,
) ![]PlanStep {
    const system_prompt =
        "You are a planning AI that creates step-by-step plans for software development tasks.\n" ++
        "Given a user request, create a detailed plan with specific steps.\n" ++
        "Each step should specify:\n" ++
        "1. A description of what to do\n" ++
        "2. The tool to use (file_read, file_write, apply_patch, shell_run, web_search, web_fetch)\n" ++
        "3. The arguments for the tool\n\n" ++
        "Respond in JSON format:\n" ++
        "{\n" ++
        "  \"steps\": [\n" ++
        "    {\n" ++
        "      \"description\": \"Description of the step\",\n" ++
        "      \"tool\": \"tool_name\",\n" ++
        "      \"args\": { \"arg1\": \"value1\" }\n" ++
        "    }\n" ++
        "  ]\n" ++
        "}\n\n" ++
        "Be specific and actionable. Include all necessary steps to complete the task.";

    var msgs = [_]llm.ChatMessage{
        .{ .role = "user", .content = prompt },
    };

    const response = try llm.chatCompletion(allocator, config, config.default_model, system_prompt, &msgs);

    var parsed_value = blk: {
        var p = std.json.parseFromSlice(std.json.Value, allocator, response, .{}) catch {
            const ex = try extractJsonFromResponse(allocator, response);
            break :blk ex;
        };
        defer p.deinit();
        break :blk try cloneJsonValue(allocator, p.value);
    };

    const steps_val = parsed_value.object.get("steps") orelse return error.InvalidPlanFormat;
    if (steps_val != .array) return error.InvalidPlanFormat;

    var steps_list = std.ArrayList(PlanStep).init(allocator);
    var i: usize = 0;
    while (i < steps_val.array.items.len) : (i += 1) {
        const step = steps_val.array.items[i];
        if (step != .object) continue;
        const desc_val = step.object.get("description") orelse continue;
        const tool_val = step.object.get("tool") orelse continue;
        const args_val = step.object.get("args") orelse continue;
        if (desc_val != .string or tool_val != .string) continue;
        const desc = try allocator.dupe(u8, desc_val.string);
        const tool = try allocator.dupe(u8, tool_val.string);
        const args = try cloneJsonValue(allocator, args_val);
        try steps_list.append(.{ .description = desc, .tool = tool, .args = args });
    }

    return try steps_list.toOwnedSlice();
}

fn extractJsonFromResponse(allocator: std.mem.Allocator, response: []const u8) !std.json.Value {
    const start_opt = std.mem.indexOfScalar(u8, response, '{');
    if (start_opt == null) return error.NoJsonFound;
    const end_opt = std.mem.lastIndexOfScalar(u8, response, '}');
    if (end_opt == null) return error.NoJsonFound;
    const start = start_opt.?;
    const end_incl = end_opt.?;
    if (end_incl < start) return error.NoJsonFound;
    const json_str = response[start .. end_incl + 1];

    var p = try std.json.parseFromSlice(std.json.Value, allocator, json_str, .{});
    defer p.deinit();
    return try cloneJsonValue(allocator, p.value);
}

pub fn validatePlan(allocator: std.mem.Allocator, steps: []const PlanStep) ![]const []const u8 {
    var errors_list = std.ArrayList([]const u8).init(allocator);

    const valid_tools = [_][]const u8{
        "file_read",
        "file_write",
        "apply_patch",
        "shell_run",
        "web_search",
        "web_fetch",
        "create_checkpoint",
        "rollback",
    };

    var i: usize = 0;
    while (i < steps.len) : (i += 1) {
        const step = steps[i];
        if (step.description.len == 0) {
            try errors_list.append(try std.fmt.allocPrint(allocator, "Step {d} has no description", .{i + 1}));
        }

        var found = false;
        for (valid_tools) |t| {
            if (std.mem.eql(u8, step.tool, t)) {
                found = true;
                break;
            }
        }
        if (!found) {
            try errors_list.append(try std.fmt.allocPrint(allocator, "Step {d} uses unknown tool: {s}", .{ i + 1, step.tool }));
        }

        if (std.mem.eql(u8, step.tool, "file_read") or std.mem.eql(u8, step.tool, "file_write") or std.mem.eql(u8, step.tool, "apply_patch")) {
            const pathv = step.args.object.get("path") orelse std.json.Value{ .null = {} };
            if (pathv == .null) {
                try errors_list.append(try std.fmt.allocPrint(allocator, "Step {d} ({s}) requires 'path' argument", .{ i + 1, step.tool }));
            }
        } else if (std.mem.eql(u8, step.tool, "shell_run")) {
            const cv = step.args.object.get("command") orelse std.json.Value{ .null = {} };
            if (cv == .null) {
                try errors_list.append(try std.fmt.allocPrint(allocator, "Step {d} (shell_run) requires 'command' argument", .{i + 1}));
            }
        } else if (std.mem.eql(u8, step.tool, "web_search")) {
            const qv = step.args.object.get("query") orelse std.json.Value{ .null = {} };
            if (qv == .null) {
                try errors_list.append(try std.fmt.allocPrint(allocator, "Step {d} (web_search) requires 'query' argument", .{i + 1}));
            }
        } else if (std.mem.eql(u8, step.tool, "web_fetch")) {
            const uv = step.args.object.get("url") orelse std.json.Value{ .null = {} };
            if (uv == .null) {
                try errors_list.append(try std.fmt.allocPrint(allocator, "Step {d} (web_fetch) requires 'url' argument", .{i + 1}));
            }
        }
    }

    return try errors_list.toOwnedSlice();
}

pub fn estimatePlanCost(steps: []const PlanStep) PlanCostEstimate {
    var file_reads: usize = 0;
    var file_writes: usize = 0;
    var shell_commands: usize = 0;
    var web_requests: usize = 0;

    for (steps) |step| {
        if (std.mem.eql(u8, step.tool, "file_read")) {
            file_reads += 1;
        } else if (std.mem.eql(u8, step.tool, "file_write") or std.mem.eql(u8, step.tool, "apply_patch")) {
            file_writes += 1;
        } else if (std.mem.eql(u8, step.tool, "shell_run")) {
            shell_commands += 1;
        } else if (std.mem.eql(u8, step.tool, "web_search") or std.mem.eql(u8, step.tool, "web_fetch")) {
            web_requests += 1;
        }
    }

    const estimated_time_secs: u64 =
        @as(u64, file_reads) +
        @as(u64, file_writes) * 2 +
        @as(u64, shell_commands) * 5 +
        @as(u64, web_requests) * 3;

    return .{
        .total_steps = steps.len,
        .file_reads = file_reads,
        .file_writes = file_writes,
        .shell_commands = shell_commands,
        .web_requests = web_requests,
        .estimated_time_secs = estimated_time_secs,
    };
}

