fn validatePath(allocator: std.mem.Allocator, path: []const u8, project_id: Uuid) ![]u8 {
    var clean = std.ArrayList(u8).init(allocator);
    defer clean.deinit();

    var it = std.mem.splitScalar(u8, path, '/');
    var first = true;
    while (it.next()) |seg| {
        if (seg.len == 0 or std.mem.eql(u8, seg, ".")) continue;
        if (std.mem.eql(u8, seg, "..")) continue;
        if (!first) try clean.append('/');
        first = false;
        try clean.appendSlice(seg);
    }

    var uuid_str = try project_id.toString(allocator);
    const workspace_dir = try std.fmt.allocPrint(allocator, "/tmp/workspaces/{s}", .{uuid_str});
    const full_path = if (clean.items.len == 0)
        try allocator.dupe(u8, workspace_dir)
    else
        try std.fmt.allocPrint(allocator, "{s}/{s}", .{ workspace_dir, clean.items });

    if (!std.mem.startsWith(u8, full_path, workspace_dir)) return error.PathTraversal;

    return full_path;
}

fn fileRead(allocator: std.mem.Allocator, project_id: Uuid, args: std.json.Value) !std.json.Value {
    const pathv = args.object.get("path") orelse return error.MissingPath;
    if (pathv != .string) return error.MissingPath;
    const path = pathv.string;

    const file_path = try validatePath(allocator, path, project_id);

    const content = std.fs.cwd().readFileAlloc(allocator, file_path, 64 * 1024 * 1024) catch return error.FileReadFailed;

    var obj = try std.json.ObjectMap.init(allocator);
    try obj.put("path", .{ .string = path });
    try obj.put("content", .{ .string = content });
    return .{ .object = obj };
}

fn fileWrite(allocator: std.mem.Allocator, project_id: Uuid, args: std.json.Value) !std.json.Value {
    const pathv = args.object.get("path") orelse return error.MissingPath;
    const contentv = args.object.get("content") orelse return error.MissingContent;
    if (pathv != .string) return error.MissingPath;
    if (contentv != .string) return error.MissingContent;
    const path = pathv.string;
    const content = contentv.string;

    const file_path = try validatePath(allocator, path, project_id);

    if (std.fs.path.dirname(file_path)) |dirn| {
        std.fs.cwd().makePath(dirn) catch return error.CreateDirsFailed;
    }

    var file = std.fs.cwd().createFile(file_path, .{ .truncate = true }) catch return error.FileWriteFailed;
    defer file.close();
    try file.writeAll(content);

    var obj = try std.json.ObjectMap.init(allocator);
    try obj.put("path", .{ .string = path });
    try obj.put("success", .{ .bool = true });
    return .{ .object = obj };
}

fn applyPatch(allocator: std.mem.Allocator, project_id: Uuid, args: std.json.Value) !std.json.Value {
    const pathv = args.object.get("path") orelse return error.MissingPath;
    const patchv = args.object.get("patch") orelse return error.MissingPatch;
    if (pathv != .string) return error.MissingPath;
    if (patchv != .string) return error.MissingPatch;
    const path = pathv.string;
    const patch = patchv.string;

    const file_path = try validatePath(allocator, path, project_id);

    const current = std.fs.cwd().readFileAlloc(allocator, file_path, 64 * 1024 * 1024) catch try allocator.dupe(u8, "");
    const new_content = try applyUnifiedDiff(allocator, current, patch);

    if (std.fs.path.dirname(file_path)) |dirn| {
        std.fs.cwd().makePath(dirn) catch return error.CreateDirsFailed;
    }
    var file = std.fs.cwd().createFile(file_path, .{ .truncate = true }) catch return error.FileWriteFailed;
    defer file.close();
    try file.writeAll(new_content);

    var obj = try std.json.ObjectMap.init(allocator);
    try obj.put("path", .{ .string = path });
    try obj.put("success", .{ .bool = true });
    try obj.put("new_content", .{ .string = new_content });
    return .{ .object = obj };
}

fn parseHunkHeader(line: []const u8) ?struct { old_start: usize, old_count: usize, new_start: usize, new_count: usize } {
    if (line.len < 4) return null;
    if (!(line[0] == '@' and line[1] == '@')) return null;

    var i: usize = 2;
    while (i < line.len and line[i] == ' ') : (i += 1) {}

    if (i >= line.len or line[i] != '-') return null;
    i += 1;
    const old_start = parseNumber(line, &i) orelse return null;
    var old_count: usize = 1;
    if (i < line.len and line[i] == ',') {
        i += 1;
        old_count = parseNumber(line, &i) orelse return null;
    }

    while (i < line.len and line[i] == ' ') : (i += 1) {}
    if (i >= line.len or line[i] != '+') return null;
    i += 1;
    const new_start = parseNumber(line, &i) orelse return null;
    var new_count: usize = 1;
    if (i < line.len and line[i] == ',') {
        i += 1;
        new_count = parseNumber(line, &i) orelse return null;
    }

    return .{ .old_start = old_start, .old_count = old_count, .new_start = new_start, .new_count = new_count };
}

fn parseNumber(s: []const u8, idx: *usize) ?usize {
    var i = idx.*;
    if (i >= s.len) return null;
    var n: usize = 0;
    var any = false;
    while (i < s.len) : (i += 1) {
        const c = s[i];
        if (c < '0' or c > '9') break;
        any = true;
        n = n * 10 + @as(usize, c - '0');
    }
    if (!any) return null;
    idx.* = i;
    return n;
}

fn applyUnifiedDiff(allocator: std.mem.Allocator, original: []const u8, patch: []const u8) ![]u8 {
    var lines = std.ArrayList([]u8).init(allocator);
    defer lines.deinit();

    var orig_it = std.mem.splitScalar(u8, original, '\n');
    while (orig_it.next()) |ln| {
        try lines.append(try allocator.dupe(u8, ln));
    }

    var patch_lines = std.ArrayList([]const u8).init(allocator);
    defer patch_lines.deinit();
    var pit = std.mem.splitScalar(u8, patch, '\n');
    while (pit.next()) |ln| {
        try patch_lines.append(ln);
    }

    var i: usize = 0;
    while (i < patch_lines.items.len) {
        const line = patch_lines.items[i];
        if (std.mem.startsWith(u8, line, "@@")) {
            if (parseHunkHeader(line)) |hunk| {
                var current_line: usize = if (hunk.old_start == 0) 0 else hunk.old_start - 1;
                i += 1;
                while (i < patch_lines.items.len and !std.mem.startsWith(u8, patch_lines.items[i], "@@")) {
                    const pl = patch_lines.items[i];
                    if (pl.len > 0 and pl[0] == '-') {
                        if (current_line < lines.items.len) {
                            _ = lines.orderedRemove(current_line);
                        }
                    } else if (pl.len > 0 and pl[0] == '+') {
                        const content = pl[1..];
                        if (current_line <= lines.items.len) {
                            try lines.insert(current_line, try allocator.dupe(u8, content));
                            current_line += 1;
                        }
                    } else if ((pl.len > 0 and pl[0] == ' ') or pl.len == 0) {
                        current_line += 1;
                    }
                    i += 1;
                }
                continue;
            }
        }
        i += 1;
    }

    var out = std.ArrayList(u8).init(allocator);
    defer out.deinit();
    var li: usize = 0;
    while (li < lines.items.len) : (li += 1) {
        if (li != 0) try out.append('\n');
        try out.appendSlice(lines.items[li]);
    }
    return try out.toOwnedSlice();
}

fn runCurl(allocator: std.mem.Allocator, argv: []const []const u8, max_bytes: usize) !struct { stdout: []u8, exit_code: i32 } {
    var child = std.process.Child.init(argv, allocator);
    child.stdin_behavior = .Ignore;
    child.stdout_behavior = .Pipe;
    child.stderr_behavior = .Pipe;
    try child.spawn();

    const stdout_bytes = try child.stdout.?.readToEndAlloc(allocator, max_bytes);
    _ = child.stderr.?.readToEndAlloc(allocator, max_bytes) catch &[_]u8{};

    const term = try child.wait();
    switch (term) {
        .Exited => |code| return .{ .stdout = stdout_bytes, .exit_code = @as(i32, @intCast(code)) },
        else => return .{ .stdout = stdout_bytes, .exit_code = -1 },
    }
}

fn shellRun(allocator: std.mem.Allocator, config: *const Config, project_id: Uuid, args: std.json.Value) !std.json.Value {
    const cmdv = args.object.get("command") orelse return error.MissingCommand;
    if (cmdv != .string) return error.MissingCommand;
    const command = cmdv.string;

    const timeout_ms_val = args.object.get("timeout_ms");
    const timeout_ms: u64 = if (timeout_ms_val) |tv| switch (tv) {
        .integer => @as(u64, @intCast(tv.integer)),
        .float => @as(u64, @intFromFloat(tv.float)),
        else => 30000,
    } else 30000;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const a = arena.allocator();

    const pid_str = try project_id.toString(a);
    const url = try std.fmt.allocPrint(a, "{s}/projects/{s}/shell", .{ config.runner_url, pid_str });

    var payload_obj = try std.json.ObjectMap.init(a);
    try payload_obj.put("command", .{ .string = command });
    try payload_obj.put("timeout_ms", .{ .integer = @as(i64, @intCast(timeout_ms)) });
    var payload_val = std.json.Value{ .object = payload_obj };
    var payload_buf = std.ArrayList(u8).init(a);
    try std.json.stringify(payload_val, .{}, payload_buf.writer());
    const payload = payload_buf.items;

    const hdr = try std.fmt.allocPrint(a, "x-internal-api-key: {s}", .{config.internal_api_key});
    const max_time = try std.fmt.allocPrint(a, "{d}", .{@as(u64, @max(1, timeout_ms / 1000))});

    const argv = [_][]const u8{
        "curl",
        "-sS",
        "-X",
        "POST",
        url,
        "-H",
        hdr,
        "-H",
        "Content-Type: application/json",
        "--max-time",
        max_time,
        "--data-binary",
        payload,
    };

    const res = runCurl(allocator, &argv, 64 * 1024 * 1024) catch .{ .stdout = try allocator.dupe(u8, ""), .exit_code = -1 };
    if (res.exit_code == 0 and res.stdout.len != 0) {
        var parsed = std.json.parseFromSlice(std.json.Value, allocator, res.stdout, .{}) catch return error.RunnerResponseInvalid;
        defer parsed.deinit();
        return try cloneJsonValue(allocator, parsed.value);
    }

    const workspace = try std.fmt.allocPrint(allocator, "/tmp/workspaces/{s}", .{try project_id.toString(allocator)});
    std.fs.cwd().makePath(workspace) catch return error.CreateDirsFailed;

    const argv2 = [_][]const u8{
        "sh",
        "-c",
        command,
    };

    var child = std.process.Child.init(&argv2, allocator);
    child.cwd = workspace;
    child.stdin_behavior = .Ignore;
    child.stdout_behavior = .Pipe;
    child.stderr_behavior = .Pipe;
    try child.spawn();

    const stdout_bytes = try child.stdout.?.readToEndAlloc(allocator, 64 * 1024 * 1024);
    const stderr_bytes = try child.stderr.?.readToEndAlloc(allocator, 64 * 1024 * 1024);

    const term = try child.wait();
    var exit_code: i32 = -1;
    switch (term) {
        .Exited => |code| exit_code = @as(i32, @intCast(code)),
        else => exit_code = -1,
    }

    var obj = try std.json.ObjectMap.init(allocator);
    try obj.put("exit_code", .{ .integer = exit_code });
    try obj.put("stdout", .{ .string = stdout_bytes });
    try obj.put("stderr", .{ .string = stderr_bytes });
    return .{ .object = obj };
}

